/****** Object:  StoredProcedure [dbo].[SP_ASIGNAR_RUTA_AEROLINEA]    Script Date: 17/03/2026 23:20:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ============================================
-- SP_ASIGNAR_RUTA_AEROLINEA
-- ============================================
CREATE   PROCEDURE [dbo].[SP_ASIGNAR_RUTA_AEROLINEA]
    @ruta_id INT,
    @aerolinea_id INT,
    @precio_base DECIMAL(10,2) = NULL,
    @frecuencia_semanal INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

BEGIN TRY
BEGIN TRANSACTION;

        -- Validar que la ruta existe
        IF NOT EXISTS (SELECT 1 FROM ruta WHERE id = @ruta_id)
BEGIN
                RAISERROR('La ruta no existe', 16, 1);
                RETURN;
END

        -- Validar que la aerolínea existe
        IF NOT EXISTS (SELECT 1 FROM aerolinea WHERE id = @aerolinea_id)
BEGIN
                RAISERROR('La aerolínea no existe', 16, 1);
                RETURN;
END

        -- Insertar o reactivar
        IF EXISTS (SELECT 1 FROM ruta_aerolinea
                   WHERE ruta_id = @ruta_id AND aerolinea_id = @aerolinea_id)
BEGIN
                -- Ya existe, actualizar
UPDATE ruta_aerolinea
SET activa = 1,
    precio_base = ISNULL(@precio_base, precio_base),
    frecuencia_semanal = ISNULL(@frecuencia_semanal, frecuencia_semanal),
    fecha_fin = NULL
WHERE ruta_id = @ruta_id AND aerolinea_id = @aerolinea_id;

SELECT 'Ruta reactivada correctamente' AS Mensaje;
END
ELSE
BEGIN
                -- Nueva asignación
INSERT INTO ruta_aerolinea (ruta_id, aerolinea_id, precio_base, frecuencia_semanal)
VALUES (@ruta_id, @aerolinea_id, @precio_base, @frecuencia_semanal);

SELECT 'Ruta asignada correctamente' AS Mensaje;
END

COMMIT TRANSACTION;

END TRY
BEGIN CATCH
IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
END CATCH
END;

GO
/****** Object:  StoredProcedure [dbo].[SP_ASIGNAR_TRIPULACION]    Script Date: 17/03/2026 23:20:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE      PROCEDURE [dbo].[SP_ASIGNAR_TRIPULACION]
    @vuelo_id      INT,
    @tripulante_id INT
AS
BEGIN
    SET NOCOUNT ON;

BEGIN TRY
BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM tripulante WHERE id = @tripulante_id AND activo = 1)
BEGIN
                RAISERROR('El tripulante no está activo.', 16, 1);
                RETURN;
END

        IF EXISTS (
            SELECT 1
            FROM asignacion_tripulacion at2
                     INNER JOIN vuelo v1 ON at2.vuelo_id = v1.id
                     INNER JOIN vuelo v2 ON v2.id = @vuelo_id
            WHERE
                at2.tripulante_id = @tripulante_id
              AND v1.estado_id IN (1, 2, 3)
              AND v2.fecha_salida  < v1.fecha_llegada
              AND v2.fecha_llegada > v1.fecha_salida
        )
BEGIN
                RAISERROR('El tripulante ya está asignado a otro vuelo en ese horario.', 16, 1);
                RETURN;
END

INSERT INTO asignacion_tripulacion (tripulante_id, vuelo_id)
VALUES (@tripulante_id, @vuelo_id);

COMMIT TRANSACTION;

SELECT 'Tripulación asignada exitosamente' AS Mensaje;
END TRY
BEGIN CATCH
IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        DECLARE @err NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@err, 16, 1);
END CATCH
END;

GO
/****** Object:  StoredProcedure [dbo].[SP_AVIONES_CON_RUTAS_DISPONIBLES]    Script Date: 17/03/2026 23:20:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_AVIONES_CON_RUTAS_DISPONIBLES]
@AerolineaId INT
AS
BEGIN
    SET NOCOUNT ON;

SELECT a.*
FROM dbo.avion AS a
WHERE a.aerolinea_id = @AerolineaId
  AND a.estado_id = 1
  AND a.aeropuerto_actual_id IN (
    SELECT DISTINCT r.aeropuerto_origen_id
    FROM dbo.ruta_aerolinea AS ra
             INNER JOIN dbo.ruta AS r ON r.id = ra.ruta_id
    WHERE ra.aerolinea_id = @AerolineaId
      AND ra.activa = 1
)
  AND NOT EXISTS (
    SELECT 1
    FROM dbo.mantenimiento AS m
    WHERE m.avion_id = a.id
      AND m.estado IN ('Programado', 'En Curso', 'En Proceso')
      AND (m.fecha_fin IS NULL OR m.fecha_fin >= GETDATE())
);
END

GO
/****** Object:  StoredProcedure [dbo].[SP_BORRAR_VUELOS_EN_VUELO]    Script Date: 17/03/2026 23:20:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_BORRAR_VUELOS_EN_VUELO]
    AS
BEGIN
        SET NOCOUNT ON;

        DECLARE @EstadoVueloEnVuelo INT;
        DECLARE @EstadoAvionOperativo INT;

        -- Obtener IDs de los estados para evitar harcodearlos
SELECT @EstadoVueloEnVuelo = id FROM estado_vuelo WHERE nombre = 'En Vuelo';
SELECT @EstadoAvionOperativo = id FROM estado_avion WHERE nombre = 'Operativo';

-- Si no se encuentran, usar valores por defecto comunes
IF @EstadoVueloEnVuelo IS NULL SET @EstadoVueloEnVuelo = 3;
        IF @EstadoAvionOperativo IS NULL SET @EstadoAvionOperativo = 1;

        -- Almacenar los vuelos y aviones afectados para procesarlos
        DECLARE @VuelosAfectados TABLE (
                                           VueloId INT,
                                           AvionId INT
                                       );

INSERT INTO @VuelosAfectados (VueloId, AvionId)
SELECT id, avion_id
FROM vuelo
WHERE estado_id = @EstadoVueloEnVuelo;

BEGIN TRY
BEGIN TRANSACTION;

            -- 1. Restaurar el estado de los aviones a 'Operativo'
UPDATE a
SET a.estado_id = @EstadoAvionOperativo
    FROM avion a
                     INNER JOIN @VuelosAfectados v ON a.id = v.AvionId;

-- 2. Eliminar asignaciones de tripulación de esos vuelos
DELETE at
            FROM asignacion_tripulacion at
                     INNER JOIN @VuelosAfectados v ON at.vuelo_id = v.VueloId;

            -- 3. Eliminar los retrasos asociados a esos vuelos (si los hubiera)
            DELETE rv
            FROM retraso_vuelo rv
                     INNER JOIN @VuelosAfectados v ON rv.vuelo_id = v.VueloId;

            -- 4. Finalmente, eliminar los vuelos
            DELETE v
            FROM vuelo v
                     INNER JOIN @VuelosAfectados va ON v.id = va.VueloId;

COMMIT TRANSACTION;


END TRY
BEGIN CATCH
IF @@TRANCOUNT > 0
                ROLLBACK TRANSACTION;

            DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
            RAISERROR(@ErrorMessage, 16, 1);
END CATCH
END
GO
