CREATE   PROCEDURE [dbo].[SP_CREATE_AEROLINEA]
    @nombre NVARCHAR(100),
    @logo NVARCHAR(250),
    @codIata NVARCHAR(3)
AS
BEGIN

    IF EXISTS (SELECT 1 FROM aerolinea WHERE nombre = @nombre)
BEGIN
            DECLARE @msgNombre NVARCHAR(200) = CONCAT('Ya existe la aerolinea: ', @nombre);
            RAISERROR(@msgNombre, 16, 1);
