CREATE   PROCEDURE [dbo].[SP_DELETE_USUARIO]
@idUsuario INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Borrar relaciones primero por FK
DELETE FROM usuario_rol WHERE usuario_id = @idUsuario;
