/****** Object:  StoredProcedure [dbo].[SP_DESACTIVAR_RUTA_AEROLINEA]    Script Date: 17/03/2026 23:20:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ============================================
-- SP_DESACTIVAR_RUTA_AEROLINEA
-- ============================================
CREATE   PROCEDURE [dbo].[SP_DESACTIVAR_RUTA_AEROLINEA]
    @ruta_id INT,
    @aerolinea_id INT
AS
BEGIN
    SET NOCOUNT ON;

BEGIN TRY
BEGIN TRANSACTION;

        -- Validar que no hay vuelos activos con esta ruta
        IF EXISTS (
            SELECT 1 FROM vuelo
            WHERE ruta_id = @ruta_id
              AND aerolinea_id = @aerolinea_id
              AND estado_id IN (1, 2, 3) -- Programado, Embarcando, En Vuelo
        )
BEGIN
                RAISERROR('No se puede desactivar la ruta porque tiene vuelos activos', 16, 1);
                RETURN;
END

UPDATE ruta_aerolinea
SET activa = 0,
    fecha_fin = GETDATE()
WHERE ruta_id = @ruta_id
  AND aerolinea_id = @aerolinea_id;

IF @@ROWCOUNT = 0
BEGIN
                RAISERROR('No se encontró la asignación de ruta', 16, 1);
                RETURN;
END

SELECT 'Ruta desactivada correctamente' AS Mensaje;

COMMIT TRANSACTION;

END TRY
BEGIN CATCH
IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
END CATCH
END;

GO
/****** Object:  StoredProcedure [dbo].[SP_FLOTAS_PAGINADO]    Script Date: 17/03/2026 23:20:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_FLOTAS_PAGINADO]
    @PageNumber     INT           = 1,
    @PageSize       INT           = 10,
    @EstadoId       INT           = NULL,
    @AerolineaId    INT           = NULL,
    @Busqueda       NVARCHAR(100) = NULL,
    @TotalRegistros INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    IF @PageNumber < 1  SET @PageNumber = 1;
    IF @PageSize   < 1  SET @PageSize   = 10;
    IF @PageSize   > 100 SET @PageSize  = 100;



SELECT @TotalRegistros = COUNT(*)
FROM V_FLOTA_ESTADO as vf
WHERE
    (@EstadoId    IS NULL OR vf.idestado    = @EstadoId)
  AND (@AerolineaId IS NULL OR vf.id_aerolinea = @AerolineaId)
  AND (@Busqueda    IS NULL OR
       vf.matricula    LIKE '%' + @Busqueda + '%' OR
       vf.nombre_modelo     LIKE '%' + @Busqueda + '%' OR
       vf.capacidad_total    LIKE '%' + @Busqueda + '%' OR
       vf.ubicacion     LIKE '%' + @Busqueda + '%' OR
       vf.vuelo_actual    LIKE '%' + @Busqueda + '%'
    );


SELECT
    vf.*,
    @TotalRegistros                                              AS total_registros,
    @PageNumber                                                  AS pagina_actual,
    @PageSize                                                    AS registros_por_pagina,
    CEILING(CAST(@TotalRegistros AS FLOAT) / @PageSize)         AS total_paginas
FROM V_FLOTA_ESTADO as vf
WHERE
    (@AerolineaId IS NULL OR vf.id_aerolinea = @AerolineaId)


  AND (@EstadoId IS NULL OR vf.idestado = @EstadoId)

  AND (@Busqueda    IS NULL OR
       vf.matricula    LIKE '%' + @Busqueda + '%' OR
       vf.nombre_modelo     LIKE '%' + @Busqueda + '%' OR
       vf.capacidad_total   LIKE '%' + @Busqueda + '%' OR
       vf.ubicacion     LIKE '%' + @Busqueda + '%' OR
       vf.vuelo_actual     LIKE '%' + @Busqueda + '%'
    )
ORDER BY vf.matricula DESC
OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;

END;

GO
/****** Object:  StoredProcedure [dbo].[SP_GENERAR_VUELOS_HARD]    Script Date: 17/03/2026 23:20:06 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_GENERAR_VUELOS_HARD]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @AvionID INT;
    DECLARE @RutaID INT;
    DECLARE @AerolineaID INT;
    DECLARE @AeropuertoOrigenID INT;
    DECLARE @Capacidad INT;
    DECLARE @Contador INT = 0;
    DECLARE @NumVuelos INT = 5;

    -- IDs de estados (ajustar según la base de datos real si los nombres difieren)
    DECLARE @EstadoVueloEnVuelo INT;
SELECT @EstadoVueloEnVuelo = id FROM estado_vuelo WHERE nombre = 'En Vuelo';
IF @EstadoVueloEnVuelo IS NULL SET @EstadoVueloEnVuelo = 3; -- Fallback

    DECLARE @EstadoAvionEnVuelo INT;
SELECT @EstadoAvionEnVuelo = id FROM estado_avion WHERE nombre = 'En Vuelo';
-- Si no existe 'En Vuelo' tal cual, buscar algo similar o asumir ID
IF @EstadoAvionEnVuelo IS NULL SELECT @EstadoAvionEnVuelo = id FROM estado_avion WHERE nombre LIKE '%Vuelo%';

DECLARE @EstadoAvionDisponible INT;
SELECT @EstadoAvionDisponible = id FROM estado_avion WHERE nombre = 'Operativo' OR nombre = 'Disponible';
IF @EstadoAvionDisponible IS NULL SET @EstadoAvionDisponible = 1; -- Fallback

    WHILE @Contador < @NumVuelos
BEGIN
            SET @AvionID = NULL;
            SET @RutaID = NULL;

            -- 1. Buscar avión disponible en tierra
            -- Debe estar en estado disponible Y tener ubicación conocida
SELECT TOP 1
                @AvionID = a.id,
    @AerolineaID = a.aerolinea_id,
       @AeropuertoOrigenID = a.aeropuerto_actual_id,
       @Capacidad = m.capacidad_total
FROM avion a
         JOIN modelo_avion m ON a.modelo_id = m.id
WHERE a.estado_id = @EstadoAvionDisponible
ORDER BY NEWID();

IF @AvionID IS NOT NULL
BEGIN
                    -- 2. Buscar ruta válida desde la ubicación actual del avión
SELECT TOP 1 @RutaID = r.id
FROM ruta r
         JOIN ruta_aerolinea ra ON r.id = ra.ruta_id
WHERE ra.aerolinea_id = @AerolineaID
  AND r.aeropuerto_origen_id = @AeropuertoOrigenID
  AND ra.activa = 1
ORDER BY NEWID();

IF @RutaID IS NOT NULL
BEGIN
                            -- 3. Insertar Vuelo
                            -- Generar código de vuelo aleatorio (ej: AE-1234)
                            DECLARE @NumVueloRandom NVARCHAR(10);
                            SET @NumVueloRandom = (SELECT codigo_iata FROM aerolinea WHERE id = @AerolineaID)
                                + CAST(ABS(CHECKSUM(NEWID()) % 9000) + 1000 AS NVARCHAR(10));

INSERT INTO vuelo (
    numero_vuelo,
    aerolinea_id,
    ruta_id,
    avion_id,
    fecha_salida,
    fecha_llegada,
    estado_id,
    puerta,
    capacidad_total,
    pasajeros_confirmados,
    pasajeros_embarcados
)
VALUES (
           @NumVueloRandom,
           @AerolineaID,
           @RutaID,
           @AvionID,
           GETDATE(), -- Salida YA
           DATEADD(MINUTE, (SELECT distancia_km FROM ruta WHERE id = @RutaID) / 10, GETDATE()), -- Estimado burdo de duración
           @EstadoVueloEnVuelo,
           'G' + CAST(ABS(CHECKSUM(NEWID()) % 20) + 1 AS NVARCHAR(5)),
           @Capacidad,
           CAST(@Capacidad * 0.85 AS INT),
           CAST(@Capacidad * 0.85 AS INT)
       );

-- 4. Actualizar estado del avión a 'En Vuelo'
-- Y poner aeropuerto_actual a NULL o dejarlo en origen hasta que llegue?
-- Normalmente al despegar deja de estar en el aeropuerto.
IF @EstadoAvionEnVuelo IS NOT NULL
BEGIN
UPDATE avion
SET estado_id = @EstadoAvionEnVuelo
WHERE id = @AvionID;
END

                            SET @Contador = @Contador + 1;
END
END
ELSE
BEGIN
                    -- No hay más aviones disponibles
                    BREAK;
END
END
END
GO
