@aerolinea_id INT
AS
BEGIN
    SET NOCOUNT ON;

SELECT
    ev.nombre AS estado,
    COUNT(v.id) AS total
FROM estado_vuelo ev
         LEFT JOIN vuelo v ON v.estado_id = ev.id AND v.aerolinea_id = @aerolinea_id
GROUP BY ev.id, ev.nombre
ORDER BY COUNT(v.id) DESC;
